function setPath(obj, dotted, value) {
  const parts = dotted.split('.');
  let cur = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (typeof cur[parts[i]] !== 'object' || cur[parts[i]] === null) cur[parts[i]] = {};
    cur = cur[parts[i]];
  }
  cur[parts[parts.length - 1]] = value;
}

for (const [locale, map] of Object.entries(BY_LOCALE)) {
  const p = path.join(locDir, `${locale}.json`);
  const dict = JSON.parse(fs.readFileSync(p, 'utf8'));
  for (const [k, v] of Object.entries(map)) setPath(dict, k, v);
  fs.writeFileSync(p, `${JSON.stringify(dict, null, 2)}\n`);
  console.log('patched', locale, Object.keys(map).length);
}
